const BASE = "https://api.upstream.example";

export async function call(path, body, fetchImpl = fetch) {
  const response = await fetchImpl(`${BASE}${path}`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });

  if (!response.ok) {
    throw new Error(`upstream ${response.status} on ${path}`);
  }

  return response.json();
}

const STEPS = ["build", "upload", "activate"];

// A target implements one function per step. Register new ones (e.g. s3) here.
const boxes = {
  build() {},
  upload() {},
  activate() {},
};

export const TARGETS = { boxes };

export function deploy(args, log = console.log, targets = TARGETS) {
  const dryRun = args.includes("--dry-run");
  const target = resolveTarget(args, targets);

  for (const step of STEPS) {
    log(`-> ${step}`);
    if (!dryRun) {
      target[step]();
    }
  }

  log(dryRun ? "dry run: 3 steps skipped" : "deployed: 3 steps");
}

function resolveTarget(args, targets) {
  const i = args.indexOf("--target");
  const name = i === -1 ? "boxes" : args[i + 1];
  const target = Object.hasOwn(targets, name) ? targets[name] : undefined;
  if (!target) {
    throw new Error(`unknown target: ${name}`);
  }
  for (const step of STEPS) {
    if (typeof target[step] !== "function") {
      throw new Error(`target ${name} does not implement ${step}`);
    }
  }
  return target;
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { deploy } from "../src/cli/deploy.js";

function capture() {
  const lines = [];
  return { lines, log: (line) => lines.push(line) };
}

test("dry run skips the steps and says so", async () => {
  const { lines, log } = capture();
  await deploy(["--dry-run"], log);
  assert.equal(lines.at(-1), "dry run: 3 steps skipped");
});

test("a full deploy reports every step", async () => {
  const { lines, log } = capture();
  await deploy([], log);
  assert.deepEqual(lines, ["-> build", "-> upload", "-> activate", "deployed: 3 steps"]);
});

function recordingTarget() {
  const calls = [];
  return {
    calls,
    target: {
      name: "fake",
      build: () => calls.push("build"),
      upload: () => calls.push("upload"),
      activate: () => calls.push("activate"),
    },
  };
}

test("deploy runs the three steps against the target it is given", async () => {
  const { calls, target } = recordingTarget();
  await deploy([], () => {}, target);
  assert.deepEqual(calls, ["build", "upload", "activate"]);
});

test("dry run never touches the target", async () => {
  const { calls, target } = recordingTarget();
  await deploy(["--dry-run"], () => {}, target);
  assert.deepEqual(calls, []);
});

test("a target missing a step is rejected before anything runs", async () => {
  const { calls, target } = recordingTarget();
  delete target.activate;
  await assert.rejects(deploy([], () => {}, target), /target "fake" is missing step: activate/);
  assert.deepEqual(calls, []);
});

test("async steps finish in order before deploy reports success", async () => {
  const events = [];
  const later = (name) => () =>
    new Promise((resolve) => setTimeout(() => { events.push(name); resolve(); }, 5));
  const target = { name: "slow", build: later("build"), upload: later("upload"), activate: later("activate") };
  await deploy([], (line) => events.push(line), target);
  assert.deepEqual(events, ["-> build", "build", "-> upload", "upload", "-> activate", "activate", "deployed: 3 steps"]);
});

test("a failing async step fails the deploy and stops later steps", async () => {
  const { calls, target } = recordingTarget();
  target.upload = async () => { throw new Error("bucket gone"); };
  const { lines, log } = capture();
  await assert.rejects(deploy([], log, target), /bucket gone/);
  assert.deepEqual(calls, ["build"]);
  assert.ok(!lines.includes("deployed: 3 steps"));
});

